double elapsed(Clock::time_point a,Clock::time_point b){return std::chrono::duration<double,std::milli>(b-a).count();}
uint32_t integer(const std::string& s){uint32_t v;auto [end,error]=std::from_chars(s.data(),s.data()+s.size(),v);if(error!=std::errc{}||end!=s.data()+s.size())throw std::invalid_argument("unsigned integer required");return v;}
void fresh(const std::string& p){if(std::filesystem::symlink_status(p).type()!=std::filesystem::file_type::not_found)throw std::invalid_argument("fresh output required");}
void write(const std::string& path,const void* data,size_t bytes){fresh(path);int fd=::open(path.c_str(),O_WRONLY|O_CREAT|O_EXCL|O_CLOEXEC,0666);if(fd<0)throw std::runtime_error("exclusive output create failed");size_t offset=0;while(offset<bytes){auto n=::write(fd,static_cast<const char*>(data)+offset,bytes-offset);if(n<0&&errno==EINTR)continue;if(n<=0){::close(fd);throw std::runtime_error("output write failed");}offset+=size_t(n);}if(::close(fd))throw std::runtime_error("output close failed");}
json summary(std::vector<double> v){std::sort(v.begin(),v.end());return {{"p50",v[v.size()/2]},{"p95",v[std::min(v.size()-1,v.size()*95/100)]},{"mean",std::accumulate(v.begin(),v.end(),0.)/v.size()}};}
void verify_stereo_integer(StereoConfig config,const DaxaStereoReadback& actual,const DaxaStereoReadback& reference,uint32_t bits){
    if(actual.census!=reference.census||actual.census_valid!=reference.census_valid||actual.costs!=reference.costs||actual.sums!=reference.sums||actual.validity!=reference.validity)throw std::runtime_error("GPU-input stereo integer/Census/mask reference mismatch");
    if(bits!=8&&bits!=16)throw std::runtime_error("packed diagnostic requires8/16bit layout");auto components=32/bits,words=(config.disparities+components-1)/components;std::vector<uint32_t> expected_words(size_t(config.width)*config.height*words);
    // Pack SCALAR sums minus paths*C, independently of reconstructed GPU sums.
    // Zero initialization also proves unused tail fields in ACTUAL GPU words.
    for(size_t i=0;i<size_t(config.width)*config.height;++i)for(uint32_t d=0;d<config.disparities;++d){auto index=i*config.disparities+d;auto base=config.paths*reference.costs[index];if(reference.sums[index]<base||reference.sums[index]-base>config.paths*config.p2)throw std::runtime_error("scalar residual violates packed penalty bound");expected_words[i*words+d/components]|=(reference.sums[index]-base)<<((d%components)*bits);}
    if(actual.packed_penalties!=expected_words)throw std::runtime_error("actual GPU-input packed words differ from independent scalar residual oracle");
}
